-- SOURCE CANDIDATE: current independently reviewed business components only.
-- No group-score restoration, financial authority, model call or formal semantic approval.
BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL statement_timeout='30s';SET LOCAL lock_timeout='2s';
SELECT pg_advisory_xact_lock(64221022);
DO $candidate$
DECLARE targets oid[]:=ARRAY[to_regprocedure('public.vnext_thesis_command_v1(text,text,jsonb)')::oid,to_regprocedure('public.vnext_current_deep_score_v1(jsonb,uuid,text)')::oid,to_regprocedure('public.vnext_provider_command_v1(text,text,jsonb)')::oid];
 additions oid[]:=ARRAY[]::oid[];before_namespace jsonb;after_namespace jsonb;constraint_metadata jsonb;constraint_definition text;target oid;source text;changed text;definition text;metadata jsonb;
 catalog_sql constant text:=$catalog$
 SELECT jsonb_build_object(
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.oid='public'::regnamespace),
  'routines',(SELECT coalesce(jsonb_agg(CASE WHEN p.oid=ANY($1) THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND NOT(p.oid=ANY($2))),
  'relations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='public'::regnamespace),
  'columns',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attrelid,a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_type t WHERE t.typnamespace='public'::regnamespace),
  'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_constraint c WHERE c.connamespace='public'::regnamespace AND NOT(c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check')),
  'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_attrdef d WHERE d.adrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'rules',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.oid),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'operators',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.oid),'[]'::jsonb) FROM pg_operator o WHERE o.oprnamespace='public'::regnamespace),
  'collations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_collation c WHERE c.collnamespace='public'::regnamespace),
  'defaultAcls',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_default_acl a WHERE a.defaclnamespace IN(0,'public'::regnamespace)),
  'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM pg_roles r),
  'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member),'[]'::jsonb) FROM pg_auth_members m))
 $catalog$;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' OR array_position(targets,NULL) IS NOT NULL THEN RAISE EXCEPTION 'vnext_business_prerequisites_missing';END IF;
 IF to_regprocedure('public.vnext_business_criteria_current_v1(uuid,text)') IS NOT NULL OR to_regprocedure('public.vnext_business_projection_v1(jsonb,uuid,text)') IS NOT NULL THEN RAISE EXCEPTION 'vnext_business_first_install_required';END IF;
 IF NOT EXISTS(SELECT FROM pg_roles role_row WHERE role_row.rolname='stockinsider_vnext_owner' AND NOT role_row.rolcanlogin AND NOT role_row.rolsuper AND NOT role_row.rolcreatedb AND NOT role_row.rolcreaterole AND NOT role_row.rolreplication AND NOT role_row.rolbypassrls AND role_row.rolconfig IS NULL)
  OR EXISTS(SELECT FROM pg_auth_members WHERE roleid='stockinsider_vnext_owner'::regrole OR member='stockinsider_vnext_owner'::regrole) OR EXISTS(SELECT FROM pg_db_role_setting WHERE setrole='stockinsider_vnext_owner'::regrole) THEN RAISE EXCEPTION 'vnext_business_owner_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_cancellation_original_v1(jsonb,jsonb,text,timestamp with time zone)') AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='318f6ccedbe1f9e1ec41aaba0a141eced386d9bf5c9a16bc72427b81e7aabadd') THEN RAISE EXCEPTION 'vnext_business_original_dependency_changed';END IF;
 SELECT pg_get_constraintdef(c.oid),to_jsonb(c)-'oid'-'conbin' INTO constraint_definition,constraint_metadata FROM pg_constraint c WHERE c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check';
 IF obj_description((SELECT c.oid FROM pg_constraint c WHERE c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check'),'pg_constraint') IS NOT NULL OR constraint_definition IS DISTINCT FROM 'CHECK ((prompt_version = ANY (ARRAY[''vnext-research-worker-v1''::text, ''vnext-research-worker-v2''::text, ''vnext-research-worker-v3''::text, ''vnext-research-worker-v4''::text])))' THEN RAISE EXCEPTION 'vnext_business_prompt_predecessor';END IF;
 EXECUTE catalog_sql INTO before_namespace USING targets,additions;
 EXECUTE $create_vnext_business_criteria_current_v1$CREATE FUNCTION public.vnext_business_criteria_current_v1(p_revision uuid,p_input_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$DECLARE pub public.vnext_publications_v1; job public.vnext_jobs_v1; frozen jsonb; author_call public.vnext_provider_invocations_v1; reviewer_call public.vnext_provider_invocations_v1; author_input jsonb; reviewer_input jsonb;
 claim jsonb; annotation jsonb; checked jsonb; assessment jsonb; evidence jsonb; criterion text; criteria jsonb:='[]'::jsonb; met boolean; gap text; annotation_hash text;
BEGIN
 IF p_revision IS NULL OR coalesce(p_input_hash,'') !~ '^[a-f0-9]{64}$' THEN RETURN NULL; END IF;
 SELECT * INTO pub FROM public.vnext_publications_v1 WHERE revision_id=p_revision;
 SELECT * INTO job FROM public.vnext_jobs_v1 WHERE job_id=pub.job_id;
 SELECT preparation.evidence INTO frozen FROM public.vnext_preparations_v1 preparation WHERE preparation.job_id=pub.job_id;
 IF pub.revision_id IS NULL OR pub.input_hash IS DISTINCT FROM p_input_hash OR job.state IS DISTINCT FROM 'published' OR job.symbol IS DISTINCT FROM pub.symbol OR job.input_hash IS DISTINCT FROM pub.input_hash OR pub.content IS DISTINCT FROM job.author_result
  OR NOT EXISTS(SELECT FROM public.vnext_members_v1 member WHERE member.symbol=pub.symbol AND member.state<>'exited' AND member.contraindication IS FALSE AND member.input_hash=pub.input_hash)
  OR EXISTS(SELECT FROM public.vnext_publications_v1 newer WHERE newer.symbol=pub.symbol AND (newer.published_at,newer.revision_id)>(pub.published_at,pub.revision_id))
  OR public.vnext_input_sources_current_v1(frozen,pub.symbol) IS DISTINCT FROM true OR job.sources_read_at IS NULL OR job.author_principal IS NULL OR job.reviewer_principal IS NULL OR job.author_principal=job.reviewer_principal OR job.execution_id IS NULL OR job.reviewer_execution IS NULL OR job.execution_id=job.reviewer_execution
  OR job.reviewer_result->>'approved' IS DISTINCT FROM 'true' OR job.reviewer_result->>'authorOutputHash' IS DISTINCT FROM job.author_result->>'outputHash' THEN RETURN NULL; END IF;
 SELECT * INTO author_call FROM public.vnext_provider_invocations_v1 WHERE job_id=job.job_id AND task='author';
 SELECT * INTO reviewer_call FROM public.vnext_provider_invocations_v1 WHERE job_id=job.job_id AND task='reviewer';
 IF author_call.invocation_id IS NULL OR reviewer_call.invocation_id IS NULL OR author_call.invocation_id=reviewer_call.invocation_id OR author_call.state IS DISTINCT FROM 'completed' OR reviewer_call.state IS DISTINCT FROM 'completed'
  OR author_call.provider IS DISTINCT FROM 'openai-responses' OR reviewer_call.provider IS DISTINCT FROM 'openai-responses' OR coalesce(author_call.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR coalesce(reviewer_call.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR author_call.provider_response_id=reviewer_call.provider_response_id
  OR author_call.prompt_version IS DISTINCT FROM 'vnext-research-worker-v5' OR reviewer_call.prompt_version IS DISTINCT FROM 'vnext-research-worker-v5'
  OR author_call.principal IS DISTINCT FROM job.author_principal OR reviewer_call.principal IS DISTINCT FROM job.reviewer_principal OR author_call.execution_id IS DISTINCT FROM job.execution_id OR reviewer_call.execution_id IS DISTINCT FROM job.reviewer_execution
  OR jsonb_typeof(job.author_result) IS DISTINCT FROM 'object' OR job.author_result->>'schemaVersion' IS DISTINCT FROM 'stockinsider-vnext-research-v1' OR job.author_result->>'inputHash' IS DISTINCT FROM job.input_hash OR job.author_result->>'model' IS DISTINCT FROM author_call.model OR job.author_result->>'modelVersion' IS DISTINCT FROM author_call.model_version OR job.reviewer_result->>'modelVersion' IS DISTINCT FROM reviewer_call.model_version
  OR coalesce(job.author_result->>'outputHash','') !~ '^[a-f0-9]{64}$' OR job.author_result->>'outputHash' IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1((job.author_result - 'outputHash'::text)),'UTF8')),'hex')
  OR author_call.input_hash IS DISTINCT FROM job.input_hash OR reviewer_call.input_hash IS DISTINCT FROM job.input_hash OR author_call.normalized_output IS DISTINCT FROM job.author_result OR reviewer_call.normalized_output IS DISTINCT FROM job.reviewer_result
  OR author_call.settled_at IS NULL OR reviewer_call.settled_at IS NULL OR author_call.settled_at<author_call.started_at OR reviewer_call.settled_at<reviewer_call.started_at OR author_call.settled_at>author_call.deadline_at OR reviewer_call.settled_at>reviewer_call.deadline_at
  OR job.sources_read_at<author_call.settled_at OR job.sources_read_at>reviewer_call.started_at OR pub.published_at<reviewer_call.settled_at
  OR author_call.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(author_call.frozen_request),'UTF8')),'hex') OR reviewer_call.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(reviewer_call.frozen_request),'UTF8')),'hex')
  OR encode(sha256(convert_to(author_call.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM 'f4bcd4f44fabc24f850e35b17ecfa62a60ca4e679564b93cd9399bc6c4ecec13' OR encode(sha256(convert_to(reviewer_call.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM '5d195c927b14ef3801b2c0e1f1ead57c2f2a0b325d5e717eb435b8c6c639831a'
  OR author_call.frozen_request->>'model' IS DISTINCT FROM author_call.model OR reviewer_call.frozen_request->>'model' IS DISTINCT FROM reviewer_call.model THEN RETURN NULL; END IF;
 author_input:=(author_call.frozen_request->>'input')::jsonb;reviewer_input:=(reviewer_call.frozen_request->>'input')::jsonb;
 IF author_input IS DISTINCT FROM jsonb_build_object('schemaVersion','vnext-worker-input-v1','task','author','jobId',job.job_id,'executionId',job.execution_id,'inputHash',job.input_hash,'evidence',jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence'),'symbol',job.symbol) OR reviewer_input IS DISTINCT FROM jsonb_build_object('schemaVersion','vnext-worker-input-v1','task','reviewer','jobId',job.job_id,'executionId',job.reviewer_execution,'inputHash',job.input_hash,'evidence',jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence'),'symbol',job.symbol,'authorArtifact',job.author_result) THEN RETURN NULL;END IF;
 IF author_input->>'jobId' IS DISTINCT FROM job.job_id::text OR reviewer_input->>'jobId' IS DISTINCT FROM job.job_id::text OR author_input->>'executionId' IS DISTINCT FROM job.execution_id::text OR reviewer_input->>'executionId' IS DISTINCT FROM job.reviewer_execution::text
  OR author_input->>'symbol' IS DISTINCT FROM job.symbol OR reviewer_input->>'symbol' IS DISTINCT FROM job.symbol OR author_input->>'task' IS DISTINCT FROM 'author' OR reviewer_input->>'task' IS DISTINCT FROM 'reviewer' OR author_input->>'inputHash' IS DISTINCT FROM job.input_hash OR reviewer_input->>'inputHash' IS DISTINCT FROM job.input_hash
  OR author_input->'evidence' IS DISTINCT FROM jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence') OR reviewer_input->'evidence' IS DISTINCT FROM author_input->'evidence' OR reviewer_input->'authorArtifact' IS DISTINCT FROM job.author_result THEN RETURN NULL; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(job.author_result->'claims') candidate WHERE candidate ? 'business' AND (jsonb_typeof(candidate->'business') IS DISTINCT FROM 'object' OR coalesce(candidate->'business'->>'criterion','') NOT IN('competitive_advantage','thesis_risk_analysis'))) THEN RETURN NULL;END IF;
 FOREACH criterion IN ARRAY ARRAY['competitive_advantage','thesis_risk_analysis'] LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(job.author_result->'claims') candidate WHERE candidate->'business'->>'criterion'=criterion)>1 THEN RETURN NULL;END IF;
  SELECT candidate.value INTO claim FROM jsonb_array_elements(job.author_result->'claims') candidate WHERE candidate.value->'business'->>'criterion'=criterion;
  IF claim IS NULL THEN criteria:=criteria||jsonb_build_array(jsonb_build_object('criterion',criterion,'annotationHash',NULL,'sourceId',NULL,'sourceHash',NULL,'observedAt',NULL,'met',NULL,'gap','component_annotation_missing'));CONTINUE;END IF;
  annotation:=claim->'business';
  IF jsonb_typeof(annotation) IS DISTINCT FROM 'object' OR NOT(annotation ?& ARRAY['schemaVersion','criterion','outcome','symbol','evidenceId','contentHash','field','startCp','endCp','quote']) OR (SELECT count(*) FROM jsonb_object_keys(annotation))<>10
   OR EXISTS(SELECT FROM unnest(ARRAY['schemaVersion','criterion','outcome','symbol','evidenceId','contentHash','field','quote']) field_name WHERE jsonb_typeof(annotation->field_name) IS DISTINCT FROM 'string')
   OR annotation->>'schemaVersion' IS DISTINCT FROM 'vnext-business-annotation-v1' OR annotation->>'symbol' IS DISTINCT FROM pub.symbol OR annotation->>'criterion' IS DISTINCT FROM criterion OR coalesce(annotation->>'outcome','') NOT IN('met','not_met','unknown')
   OR claim->>'kind' IS DISTINCT FROM 'assumption' OR claim ? 'numeric' OR claim ? 'semantic' OR claim ? 'cancellation' OR jsonb_typeof(claim->'evidenceIds') IS DISTINCT FROM 'array' OR jsonb_array_length(claim->'evidenceIds')<>1 OR claim->'evidenceIds'->>0 IS DISTINCT FROM annotation->>'evidenceId' THEN RETURN NULL;END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(frozen->'evidence') original_item WHERE original_item->>'id'=annotation->>'evidenceId')<>1 THEN RETURN NULL;END IF;
  SELECT original_item.value INTO evidence FROM jsonb_array_elements(frozen->'evidence') original_item WHERE original_item.value->>'id'=annotation->>'evidenceId';
  IF public.vnext_cancellation_original_v1(evidence,jsonb_build_object('evidenceId',annotation->'evidenceId','contentHash',annotation->'contentHash','field',annotation->'field','startCp',annotation->'startCp','endCp',annotation->'endCp','quote',annotation->'quote'),pub.symbol,(frozen->>'cutoff')::timestamptz) IS DISTINCT FROM true THEN RETURN NULL;END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(job.reviewer_result->'claimChecks') check_row WHERE check_row->>'claimId'=claim->>'id')<>1 THEN RETURN NULL;END IF;
  SELECT check_row.value INTO checked FROM jsonb_array_elements(job.reviewer_result->'claimChecks') check_row WHERE check_row.value->>'claimId'=claim->>'id';assessment:=checked->'businessAssessment';
  IF checked->>'verdict' IS DISTINCT FROM 'supported' OR NOT EXISTS(SELECT FROM jsonb_array_elements(checked->'sources') original_source WHERE original_source->>'id'=evidence->>'id' AND original_source->>'contentHash'=evidence->>'contentHash') OR jsonb_typeof(assessment) IS DISTINCT FROM 'object'
   OR NOT(assessment ?& ARRAY['schemaVersion','annotation','assessment','reason']) OR (SELECT count(*) FROM jsonb_object_keys(assessment))<>4 OR assessment->>'schemaVersion' IS DISTINCT FROM 'vnext-business-assessment-v1' OR assessment->'annotation' IS DISTINCT FROM annotation
   OR jsonb_typeof(assessment->'assessment') IS DISTINCT FROM 'string' OR jsonb_typeof(assessment->'reason') IS DISTINCT FROM 'string' OR char_length(btrim(assessment->>'reason')) NOT BETWEEN 20 AND 2000 OR coalesce(assessment->>'assessment','') NOT IN('supported_inference','insufficient') OR assessment->>'assessment'='insufficient' AND annotation->>'outcome'<>'unknown' THEN RETURN NULL;END IF;
  annotation_hash:=encode(sha256(convert_to(public.vnext_catalog_canonical_v1(annotation),'UTF8')),'hex');
  gap:=CASE WHEN assessment->>'assessment'='insufficient' THEN 'component_assessment_insufficient' WHEN annotation->>'outcome'='unknown' THEN 'component_outcome_unknown' ELSE NULL END;
  met:=CASE WHEN gap IS NOT NULL THEN NULL ELSE annotation->>'outcome'='met' END;
  criteria:=criteria||jsonb_build_array(jsonb_build_object('criterion',criterion,'annotationHash',annotation_hash,'sourceId',evidence->>'id','sourceHash',evidence->>'contentHash','observedAt',evidence->'value'->>'publishedAt','met',met,'gap',gap));
 END LOOP;
 RETURN jsonb_build_object('schemaVersion','vnext-business-receipt-v1','revisionId',pub.revision_id,'inputHash',pub.input_hash,'symbol',pub.symbol,'authorInvocation',author_call.invocation_id,'reviewerInvocation',reviewer_call.invocation_id,'authorExecution',job.execution_id,'reviewerExecution',job.reviewer_execution,'criteria',criteria);
END
;$function$;$create_vnext_business_criteria_current_v1$;
 ALTER FUNCTION public.vnext_business_criteria_current_v1(uuid,text) OWNER TO stockinsider_vnext_owner;
 REVOKE ALL ON FUNCTION public.vnext_business_criteria_current_v1(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
 EXECUTE $create_vnext_business_projection_v1$CREATE FUNCTION public.vnext_business_projection_v1(base jsonb,p_revision uuid,p_input_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$DECLARE receipt jsonb; competitive jsonb; risk_analysis jsonb;
BEGIN
 IF base IS NULL OR jsonb_typeof(base->'factors') IS DISTINCT FROM 'object' THEN RETURN base;END IF;
 receipt:=public.vnext_business_criteria_current_v1(p_revision,p_input_hash);
 IF receipt IS NULL THEN RETURN base;END IF;
 SELECT criterion.value INTO competitive FROM jsonb_array_elements(receipt->'criteria') criterion WHERE criterion.value->>'criterion'='competitive_advantage';
 SELECT criterion.value INTO risk_analysis FROM jsonb_array_elements(receipt->'criteria') criterion WHERE criterion.value->>'criterion'='thesis_risk_analysis';
 -- These are explanatory components only. Original numeric group authority,
 -- original risk_bound, fixed weights and ranking totals remain unchanged.
 RETURN base||jsonb_build_object('factors',base->'factors'||jsonb_build_object(
  'profitability',coalesce(base->'factors'->'profitability','{}'::jsonb)||jsonb_build_object('businessComponent',competitive,'interpretation','labelled_inference_not_confirmed_fact','groupGap','remaining_components_not_db_verified'),
  'marketLiquidity',coalesce(base->'factors'->'marketLiquidity','{}'::jsonb)||jsonb_build_object('thesisRiskAnalysis',risk_analysis,'riskBound',NULL,'interpretation','labelled_inference_not_confirmed_fact','groupGap','remaining_components_not_db_verified')));
END
;$function$;$create_vnext_business_projection_v1$;
 ALTER FUNCTION public.vnext_business_projection_v1(jsonb,uuid,text) OWNER TO stockinsider_vnext_owner;
 REVOKE ALL ON FUNCTION public.vnext_business_projection_v1(jsonb,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
 ALTER TABLE public.vnext_provider_bindings_v1 DROP CONSTRAINT vnext_provider_bindings_v1_prompt_version_check;
 ALTER TABLE public.vnext_provider_bindings_v1 ADD CONSTRAINT vnext_provider_bindings_v1_prompt_version_check CHECK(prompt_version IN('vnext-research-worker-v1','vnext-research-worker-v2','vnext-research-worker-v3','vnext-research-worker-v4','vnext-research-worker-v5'));
 target:=to_regprocedure('public.vnext_thesis_command_v1(text,text,jsonb)')::oid;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language language ON language.oid=p.prolang WHERE p.oid=target AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prokind='f' AND language.lanname='plpgsql' AND p.prorettype='jsonb'::regtype AND NOT p.proretset AND p.pronargs=3 AND p.proargnames=ARRAY['p_principal','p_command','p_request'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='v' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL) THEN RAISE EXCEPTION 'vnext_business_original_profile_changed';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=target)<>2 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=target AND (acl.grantor<>p.proowner OR acl.privilege_type<>'EXECUTE' OR acl.is_grantable OR (acl.grantee<>p.proowner AND acl.grantee<>'service_role'::regrole))) THEN RAISE EXCEPTION 'vnext_business_original_acl_changed';END IF;
 SELECT prosrc,pg_get_functiondef(oid),to_jsonb(p)-'prosrc' INTO source,definition,metadata FROM pg_proc p WHERE oid=target;
 IF encode(sha256(convert_to(source,'UTF8')),'hex') IS DISTINCT FROM 'eea43a99a6de1fb205dbe459ff1eb4991ea27cca372aff7afdc001cbe227e181' OR octet_length(convert_to(source,'UTF8'))<>6055 THEN RAISE EXCEPTION 'vnext_business_body_predecessor';END IF;
 changed:=source;
 IF (length(changed)-length(replace(changed,$old0_0$'semanticReceipt',public.vnext_semantic_criteria_current_v1(pub.revision_id,m.input_hash))$old0_0$,'')))<>length($old0_0$'semanticReceipt',public.vnext_semantic_criteria_current_v1(pub.revision_id,m.input_hash))$old0_0$) THEN RAISE EXCEPTION 'vnext_business_single_seam_required';END IF;
 changed:=replace(changed,$old0_0$'semanticReceipt',public.vnext_semantic_criteria_current_v1(pub.revision_id,m.input_hash))$old0_0$,$new0_0$'semanticReceipt',public.vnext_semantic_criteria_current_v1(pub.revision_id,m.input_hash),'businessReceipt',public.vnext_business_criteria_current_v1(pub.revision_id,m.input_hash))$new0_0$);
 IF replace(changed,$new0_0$'semanticReceipt',public.vnext_semantic_criteria_current_v1(pub.revision_id,m.input_hash),'businessReceipt',public.vnext_business_criteria_current_v1(pub.revision_id,m.input_hash))$new0_0$,$old0_0$'semanticReceipt',public.vnext_semantic_criteria_current_v1(pub.revision_id,m.input_hash))$old0_0$) IS DISTINCT FROM source OR encode(sha256(convert_to(changed,'UTF8')),'hex') IS DISTINCT FROM 'e15c231f20c7b539b852b7be97607ac4ea4008513505c641b0fbf1609be445e7' THEN RAISE EXCEPTION 'vnext_business_inverse_parity';END IF;
 EXECUTE replace(definition,source,changed);
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE oid=target) IS DISTINCT FROM metadata OR to_regprocedure('public.vnext_thesis_command_v1(text,text,jsonb)')::oid IS DISTINCT FROM target THEN RAISE EXCEPTION 'vnext_business_metadata_changed';END IF;
 target:=to_regprocedure('public.vnext_current_deep_score_v1(jsonb,uuid,text)')::oid;
